:root {
  --ink: #f7f4ff;
  --muted: #a9a1c8;
  --dim: #6e668d;
  --cyan: #5cf8ff;
  --cyan-deep: #16c9e8;
  --pink: #ff3ca6;
  --pink-hot: #ff167d;
  --violet: #8d5bff;
  --yellow: #ffe36e;
  --bg: #05020f;
  --panel: rgba(12, 7, 29, 0.82);
  --line: rgba(255, 255, 255, 0.12);
  --display: "Arial Black", "Helvetica Neue", "Segoe UI", sans-serif;
  --mono: "SFMono-Regular", "Cascadia Code", "Roboto Mono", Menlo, Consolas, monospace;
  --body: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--body);
  overscroll-behavior: none;
}

body {
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  cursor: pointer;
  touch-action: manipulation;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 4px;
}

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: #05020f;
  touch-action: none;
}

.vignette,
.scanlines,
.flash {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}

.vignette {
  background:
    radial-gradient(ellipse at 52% 45%, transparent 34%, rgba(2, 0, 9, 0.42) 74%, rgba(2, 0, 9, 0.82) 100%),
    linear-gradient(180deg, rgba(4, 1, 12, 0.28), transparent 20%, transparent 72%, rgba(4, 1, 12, 0.6));
}

.scanlines {
  opacity: 0.16;
  background: repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.035) 0, rgba(255, 255, 255, 0.035) 1px, transparent 1px, transparent 3px);
  mix-blend-mode: overlay;
}

.flash {
  z-index: 8;
  opacity: 0;
  background: #fff;
  transition: opacity 0.18s ease-out;
}

.flash.hit {
  opacity: 0.7;
  transition: none;
}

.ui {
  position: fixed;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  padding:
    max(18px, env(safe-area-inset-top))
    max(22px, env(safe-area-inset-right))
    max(16px, env(safe-area-inset-bottom))
    max(22px, env(safe-area-inset-left));
}

/* ---------- HUD ---------- */

.hud {
  position: absolute;
  top: max(18px, env(safe-area-inset-top));
  left: max(22px, env(safe-area-inset-left));
  right: max(22px, env(safe-area-inset-right));
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 20px;
  opacity: 0;
  transform: translateY(-10px);
  transition: opacity 0.35s ease, transform 0.35s ease;
}

body.playing .hud,
body.gameover .hud,
body.paused .hud {
  opacity: 1;
  transform: none;
}

.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.brand-glyph {
  width: 29px;
  height: 29px;
  display: flex;
  align-items: flex-end;
  gap: 3px;
  padding: 5px;
  border: 1px solid rgba(92, 248, 255, 0.34);
  background: rgba(10, 8, 27, 0.46);
  transform: skew(-7deg);
}

.brand-glyph i {
  display: block;
  flex: 1;
  background: var(--cyan);
  box-shadow: 0 0 10px rgba(92, 248, 255, 0.8);
  animation: glyph 0.95s ease-in-out infinite alternate;
}

.brand-glyph i:nth-child(1) { height: 42%; animation-delay: -0.2s; }
.brand-glyph i:nth-child(2) { height: 90%; background: var(--pink); box-shadow: 0 0 10px rgba(255, 60, 166, 0.8); animation-delay: -0.5s; }
.brand-glyph i:nth-child(3) { height: 65%; animation-delay: -0.75s; }

@keyframes glyph {
  to { height: 24%; opacity: 0.6; }
}

.brand-word {
  font-family: var(--display);
  font-size: 15px;
  letter-spacing: 0.1em;
  font-weight: 900;
  white-space: nowrap;
}

.brand-word em {
  font-style: normal;
  color: var(--pink);
  margin-left: 4px;
}

.beat-hud {
  justify-self: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  padding-top: 2px;
}

.beat-dots {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 16px;
}

.beat-dots span {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.18);
  transition: transform 0.11s ease, background 0.11s ease, box-shadow 0.11s ease;
}

.beat-dots span.downbeat {
  width: 12px;
  height: 12px;
  border-color: rgba(255, 60, 166, 0.5);
}

.beat-dots span.on {
  background: var(--cyan);
  border-color: #fff;
  box-shadow: 0 0 13px var(--cyan), 0 0 4px #fff;
  transform: scale(1.45);
}

.beat-dots span.downbeat.on {
  background: var(--pink);
  box-shadow: 0 0 15px var(--pink), 0 0 5px #fff;
}

.beat-meta {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.18em;
  color: rgba(218, 211, 241, 0.62);
  white-space: nowrap;
}

.beat-meta span {
  color: var(--cyan);
}

.beat-meta b {
  color: var(--dim);
  padding: 0 3px;
}

.score-hud {
  justify-self: end;
  display: grid;
  grid-template-columns: auto auto;
  align-items: center;
  gap: 0 18px;
  text-align: right;
}

.score-main {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.micro-label {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.24em;
  color: var(--muted);
}

.score-main strong {
  font-family: var(--display);
  font-size: clamp(22px, 2.2vw, 34px);
  line-height: 0.95;
  letter-spacing: 0.045em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 22px rgba(92, 248, 255, 0.35);
}

.best-line {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  color: var(--dim);
  margin-top: 3px;
  grid-column: 1;
}

.best-line span {
  color: var(--yellow);
}

.hud-actions {
  grid-column: 2;
  grid-row: 1 / span 2;
  display: flex;
  gap: 7px;
}

.icon-btn {
  pointer-events: auto;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(11, 7, 27, 0.6);
  color: var(--muted);
  border-radius: 50%;
  transition: color 0.16s, border-color 0.16s, background 0.16s, transform 0.16s;
}

.icon-btn:hover {
  color: var(--ink);
  border-color: rgba(92, 248, 255, 0.55);
  background: rgba(24, 16, 52, 0.9);
  transform: translateY(-1px);
}

.icon-btn svg {
  width: 16px;
  height: 16px;
  fill: currentColor;
}

#muteBtn .icon-off { display: none; }
#muteBtn.muted .icon-on { display: none; }
#muteBtn.muted .icon-off { display: block; color: var(--pink); }
#pauseBtn { display: none; }
body.playing #pauseBtn { display: grid; }

/* ---------- Combo + judge ---------- */

.combo {
  position: absolute;
  top: 16.5%;
  left: 50%;
  transform: translate(-50%, -8px) scale(0.9);
  display: flex;
  align-items: baseline;
  gap: 8px;
  opacity: 0;
  transition: opacity 0.16s, transform 0.16s;
  text-shadow: 0 0 18px rgba(92, 248, 255, 0.5);
}

.combo.show {
  opacity: 1;
  transform: translate(-50%, 0) scale(1);
}

.combo span {
  font-family: var(--display);
  font-size: clamp(30px, 4vw, 54px);
  line-height: 1;
  color: #fff;
  font-style: italic;
}

.combo small {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.28em;
  color: var(--cyan);
}

.judge {
  position: absolute;
  top: 45%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--display);
  font-size: clamp(18px, 2.2vw, 28px);
  letter-spacing: 0.08em;
  font-style: italic;
  opacity: 0;
  pointer-events: none;
  text-align: center;
  white-space: nowrap;
}

.judge.pop {
  animation: judge-pop 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.judge.perfect {
  color: var(--yellow);
  text-shadow: 0 0 20px rgba(255, 227, 110, 0.75), 0 0 50px rgba(255, 60, 166, 0.4);
}

.judge.good {
  color: var(--cyan);
  text-shadow: 0 0 18px rgba(92, 248, 255, 0.65);
}

.judge.miss {
  color: var(--pink);
  text-shadow: 0 0 18px rgba(255, 60, 166, 0.6);
}

@keyframes judge-pop {
  0% { opacity: 0; transform: translate(-50%, -20%) scale(0.72); }
  18% { opacity: 1; transform: translate(-50%, -50%) scale(1.08); }
  62% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -75%) scale(0.98); }
}

/* ---------- Screens ---------- */

.screen {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.32s ease, visibility 0.32s;
}

.screen.is-visible {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.start-screen {
  justify-content: flex-start;
  padding: clamp(22px, 6vw, 100px);
  background:
    linear-gradient(90deg, rgba(5, 2, 15, 0.96) 0%, rgba(5, 2, 15, 0.82) 30%, rgba(5, 2, 15, 0.42) 55%, transparent 78%),
    radial-gradient(ellipse at 70% 65%, transparent 0, transparent 35%, rgba(5, 2, 15, 0.4) 76%);
}

.start-copy {
  position: relative;
  width: min(650px, 100%);
  transform: translateY(-2%);
  animation: enter 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes enter {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(-2%); }
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 11px;
  font-family: var(--mono);
  font-size: clamp(8px, 0.85vw, 10px);
  letter-spacing: 0.3em;
  color: var(--cyan);
  margin-bottom: clamp(14px, 2.2vh, 24px);
}

.eyebrow-line {
  width: 32px;
  height: 1px;
  background: var(--cyan);
  box-shadow: 0 0 9px var(--cyan);
}

.game-title {
  margin: 0;
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(58px, 10.4vw, 148px);
  line-height: 0.78;
  letter-spacing: -0.065em;
  transform: skew(-5deg);
  display: flex;
  flex-wrap: wrap;
  gap: 0 0.16em;
  filter: drop-shadow(0 10px 40px rgba(255, 22, 125, 0.12));
}

.title-pulse,
.title-dash {
  position: relative;
  display: inline-block;
}

.title-pulse {
  color: #fff;
  text-shadow:
    0 0 3px #fff,
    0 0 24px rgba(92, 248, 255, 0.32),
    5px 5px 0 rgba(92, 248, 255, 0.17);
}

.title-dash {
  background: linear-gradient(115deg, #ff7ac5 0%, var(--pink) 38%, var(--pink-hot) 70%, #a43cff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: 0 0 35px rgba(255, 22, 125, 0.34);
  animation: title-hum 3.4s ease-in-out infinite;
}

.title-dash::after {
  content: "";
  position: absolute;
  left: 6%;
  right: 2%;
  bottom: -4px;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--pink), var(--cyan), transparent);
  opacity: 0.7;
  box-shadow: 0 0 14px var(--pink);
}

@keyframes title-hum {
  50% { filter: brightness(1.18); }
}

.tagline {
  margin: clamp(20px, 3.6vh, 34px) 0 0;
  font-family: var(--display);
  font-weight: 800;
  font-size: clamp(17px, 2.1vw, 27px);
  line-height: 1.18;
  letter-spacing: 0.01em;
  text-transform: uppercase;
}

.tagline span {
  color: var(--muted);
  font-family: var(--body);
  font-weight: 600;
  font-size: 0.67em;
  letter-spacing: 0.08em;
}

.start-actions {
  display: flex;
  align-items: center;
  gap: clamp(18px, 3vw, 36px);
  margin-top: clamp(24px, 4.4vh, 44px);
}

.btn {
  pointer-events: auto;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 52px;
  padding: 0 28px;
  border: 1px solid transparent;
  border-radius: 3px;
  font-family: var(--display);
  font-size: 13px;
  letter-spacing: 0.16em;
  font-weight: 900;
  transition: transform 0.16s ease, box-shadow 0.16s ease, background 0.16s ease, border-color 0.16s ease;
  overflow: hidden;
}

.btn svg {
  width: 17px;
  height: 17px;
  fill: currentColor;
  flex: none;
}

.btn-primary {
  color: #140419;
  background: linear-gradient(115deg, #ff7ac5, var(--pink) 46%, #ff3d76);
  border-color: rgba(255, 255, 255, 0.36);
  box-shadow: 0 0 0 1px rgba(255, 60, 166, 0.26), 0 12px 42px rgba(255, 22, 125, 0.26), inset 0 1px 0 rgba(255, 255, 255, 0.35);
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}

.btn-primary::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: -70%;
  width: 40%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.55), transparent);
  transform: skewX(-18deg);
  transition: left 0.5s ease;
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.25), 0 16px 48px rgba(255, 22, 125, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

.btn-primary:hover::before { left: 140%; }
.btn-primary:active { transform: translateY(1px) scale(0.985); }

#startBtn {
  min-width: clamp(160px, 16vw, 204px);
  min-height: clamp(58px, 7vh, 70px);
  font-size: clamp(15px, 1.3vw, 18px);
}

.start-best {
