+      }
+    }
+  }
+
+  function updateObstacles(run, dt) {
+    const scale = view.scale;
+    const playerSize = PLAYER_SIZE * scale;
+    const pbox = {
+      x: view.playerX - playerSize * 0.35,
+      y: player.y - playerSize * 0.35,
+      w: playerSize * 0.7,
