+  }
+
+  function update(dt) {
+    const run = game.run;
+    if (!run) return;
+    run.time += dt;
+    run.beat = run.time / BEAT;
+    run.worldPos = beatPosition(run.beat);
+    run.pulse = Math.max(0, run.pulse - dt * 5);
