input.newString:
function updateDying(dt) {
  const run = game.run;
  if (!run) return;
  run.deathTimer += dt;
  run.shake = Math.max(0, run.shake - dt * 30);
  updateParticles(run, dt);
  if (run.deathTimer > 0.82) showGameOver();
}

/* ------------------------------------------------------------------ */
/* Rendering — backdrop                                               */
/* ------------------------------------------------------------------ */

function drawBackground(time, beat, activeRun) {
  const w = view.w;
  const h = view.h;
  const groundY = view.groundY;
  const scale = view.scale;
  const distance = activeRun ? activeRun.worldPos * scale : game.menuTime * 46;
  const pulse = activeRun ? Math.max(0, 1 - mod(activeRun.beat, 1) * 3.6) : 0.35 + Math.sin(time * 2.1) * 0.18;

  const sky = ctx.createLinearGradient(0, 0, 0, groundY + 20);
  sky.addColorStop(0, '#04010d');
  sky.addColorStop(0.42, '#0b0520');
  sky.addColorStop(0.72, '#1b0735');
  sky.addColorStop(1, '#2a0942');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, w, groundY + 2);

  // faint atmospheric glow behind the city
  const haze = ctx.createRadialGradient(w * 0.7, groundY - 50, 10, w * 0.7, groundY - 50, w * 0.6);
  haze.addColorStop(0, `rgba(255,60,166,${0.09 + pulse * 0.035})`);
  haze.addColorStop(0.5, 'rgba(92,248,255,0.025)');
  haze.addColorStop(1, 'rgba(4,1,13,0)');
  ctx.fillStyle = haze;
  ctx.fillRect(0, 0, w, groundY);

  // stars
  for (let i = 0; i < stars.length; i += 1) {
    const star = stars[i];
    const sx = mod(star.x * w - distance * star.depth * 0.045, w + 20) - 10;
    const sy = star.y * groundY;
    const twinkle = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(time * star.speed + star.phase));
    ctx.globalAlpha = twinkle * (0.28 + star.depth * 0.55);
    ctx.fillStyle = star.warm ? '#ffc6e4' : '#c7f8ff';
    ctx.fillRect(sx, sy, star.r, star.r);
    if (star.r > 1.2) {
      ctx.globalAlpha *= 0.35;
      ctx.fillRect(sx - 1.5, sy + star.r * 0.35, star.r + 3, 0.6);
      ctx.fillRect(sx + star.r * 0.35, sy - 1.5, 0.6, star.r + 3);
    }
  }
  ctx.globalAlpha = 1;

  // synthwave sun
  const sunR = clamp(Math.min(w, h) * 0.145, 58, 132);
  const sunX = w * 0.72;
  const sunY = groundY - sunR * 0.85 - 30;
  const sunGlow = ctx.createRadialGradient(sunX, sunY, sunR * 0.2, sunX, sunY, sunR * 2.4);
  sunGlow.addColorStop(0, `rgba(255,92,180,${0.2 + pulse * 0.05})`);
  sunGlow.addColorStop(0.5, 'rgba(255,60,166,0.07)');
  sunGlow.addColorStop(1, 'rgba(255,60,166,0)');
  ctx.fillStyle = sunGlow;
  ctx.fillRect(sunX - sunR * 2.5, sunY - sunR * 2.5, sunR * 5, sunR * 5);

  ctx.save();
  ctx.beginPath();
  ctx.arc(sunX, sunY, sunR, 0, TAU);
  ctx.clip();
  const sunFill = ctx.createLinearGradient(0, sunY - sunR, 0, sunY + sunR);
  sunFill.addColorStop(0, '#ffe98a');
  sunFill.addColorStop(0.42, '#ffb26e');
  sunFill.addColorStop(0.72, '#ff4c9d');
  sunFill.addColorStop(1, '#b42cff');
  ctx.fillStyle = sunFill;
  ctx.fillRect(sunX - sunR, sunY - sunR, sunR * 2, sunR * 2);
  ctx.fillStyle = 'rgba(7,2,19,0.86)';
  const stripeStart = sunY + sunR * 0.08;
  for (let i = 0; i < 8; i += 1) {
    const sy = stripeStart + i * sunR * 0.115;
    const sh = 2 + i * 1.3;
    ctx.fillRect(sunX - sunR, sy, sunR * 2, sh);
  }
  ctx.restore();

  ctx.save();
  ctx.beginPath();
  ctx.arc(sunX, sunY, sunR + 1.5, 0, TAU);
  ctx.strokeStyle = `rgba(255,164,218,${0.35 + pulse * 0.2})`;
  ctx.lineWidth = 1.4;
  ctx.shadowColor = '#ff3ca6';
  ctx.shadowBlur = 18;
  ctx.stroke();
  ctx.restore();

  // speed streaks
  ctx.save();
  for (let i = 0; i < streaks.length; i += 1) {
    const s = streaks[i];
    const x = mod(s.x * (w + 300) - distance * s.speed * 0.55 - time * 12, w + 300) - 150;
    const y = view.horizon + s.y * (groundY - view.horizon);
    ctx.globalAlpha = s.alpha * (activeRun ? 1 : 0.5);
    ctx.strokeStyle = s.pink ? '#ff3ca6' : '#5cf8ff';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + s.len, y);
    ctx.stroke();
  }
  ctx.restore();

  // city layers
  drawCity(cityFar, distance * 0.1, '#170b38', 0.8, time, pulse, 1);
  drawCity(cityNear, distance * 0.23, '#0d0624', 1, time, pulse, 2);

  // horizon glow
  const horizonGlow = ctx.createLinearGradient(0, groundY - 28, 0, groundY + 4);
  horizonGlow.addColorStop(0, 'rgba(255,60,166,0)');
  horizonGlow.addColorStop(0.62, `rgba(255,60,166,${0.12 + pulse * 0.04})`);
  horizonGlow.addColorStop(1, 'rgba(92,248,255,0.12)');
  ctx.fillStyle = horizonGlow;
  ctx.fillRect(0, groundY - 28, w, 32);

  drawFloor(distance, time, pulse, activeRun);
  drawMotes(time, distance);
}

function drawCity(buildings, offset, color, alpha, time, pulse, layer) {
  const groundY = view.groundY;
  const tile = CITY_TILE;
  const start = -mod(offset, tile);
  ctx.save();
  ctx.globalAlpha = alpha;
  for (let copy = 0; copy < 2; copy += 1) {
    const baseX = start + copy * tile;
    for (let i = 0; i < buildings.length; i += 1) {
      const b = buildings[i];
      const x = baseX + b.x;
      if (x > view.w + 80 || x + b.w < -80) continue;
      const y = groundY - b.h;
      ctx.fillStyle = color;
      ctx.fillRect(x, y, b.w, b.h + 1);
      ctx.fillStyle = layer === 1 ? 'rgba(255,255,255,0.035)' : 'rgba(92,248,255,0.05)';
      ctx.fillRect(x, y, b.w, 1);
      if (b.antenna) {
        ctx.fillStyle = layer === 1 ? 'rgba(255,60,166,0.3)' : 'rgba(255,60,166,0.55)';
        ctx.fillRect(x + b.w * 0.62, y - 10, 1, 10);
        ctx.globalAlpha = alpha * (0.5 + pulse * 0.5);
        ctx.fillRect(x + b.w * 0.62 - 1, y - 11, 3, 2);
        ctx.globalAlpha = alpha;
      }
      for (let j = 0; j < b.windows.length; j += 1) {
        const win = b.windows[j];
        const flicker = 0.55 + 0.45 * Math.sin(time * 1.4 + win.flicker);
        ctx.globalAlpha = alpha * (0.12 + flicker * 0.3);
        ctx.fillStyle = win.warm ? '#ffcb7a' : '#ff6fbe';
        ctx.fillRect(x + win.x, y + win.y, win.w, win.h);
      }
      ctx.globalAlpha = alpha;
    }
  }
  ctx.restore();
}

function drawFloor(distance, time, pulse, activeRun) {
  const w = view.w;
  const h = view.h;
  const groundY = view.groundY;
  const depth = h - groundY;

  const floor = ctx.createLinearGradient(0, groundY, 0, h);
  floor.addColorStop(0, '#100826');
  floor.addColorStop(0.35, '#080316');
  floor.addColorStop(1, '#020108');
  ctx.fillStyle = floor;
  ctx.fillRect(0, groundY, w, depth + 1);

  // perspective floor grid
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, groundY, w, depth);
  ctx.clip();

  const horizonX = w * 0.5;
  const spacing = Math.max(88, w / 9);
