1262:   function updateParticles(run, dt) {
1263:     const speed = BASE_SPEED * view.scale * speedFactor(run.beat);
1264:     for (let i = run.particles.length - 1; i >= 0; i -= 1) {
1265:       const p = run.particles[i];
1266:       p.life -= dt;
1267:       if (p.life <= 0) {
1268:         run.particles.splice(i, 1);
1269:         continue;
1270:       }
1271:       p.vy += p.gravity * dt;
1272:       p.x += (p.vx - speed * 0.18) * dt;
1273:       p.y += p.vy * dt;
1274:       p.rot += p.vr * dt;
1275:     }
1276:     for (let i = run.rings.length - 1; i >= 0; i -= 1) {
1277:       const ring = run.rings[i];
1278:       ring.life -= dt;
1279:       if (ring.life <= 0) {
1280:         run.rings.splice(i, 1);
1281:         continue;
1282:       }
1283:       const progress = 1 - ring.life / ring.maxLife;
1284:       ring.r = lerp(ring.r, ring.max, Math.min(1, dt * (4 + progress * 5)));
1285:     }
1286:     for (let i = run.floats.length - 1; i >= 0; i -= 1) {
1287:       const f = run.floats[i];
1288:       f.life -= dt;
1289:       f.y -= 34 * dt;
1290:       if (f.life <= 0) run.floats.splice(i, 1);
1291:     }
1292:   }
