1294:   function update(dt) {
1295:     const run = game.run;
1296:     if (!run) return;
1297:     run.time += dt;
1298:     run.beat = run.time / BEAT;
1299:     run.worldPos = beatPosition(run.beat);
1300:     run.pulse = Math.max(0, run.pulse - dt * 5);
1301:     run.shake = Math.max(0, run.shake - dt * 45);
1302:     const tier = sectionForBeat(run.beat);
1303:     if (tier !== run.tier) {
1304:       run.tier = tier;
1305:       updateSectionUI(tier);
1306:       if (tier > 0) showToast(sections[tier], 'The track is speeding up', 1700);
1307:     }
1308: 
1309:     updatePlayer(dt);
1310:     updateObstacles(run, dt);
1311:     if (game.state !== 'playing') return;
1312: 
1313:     ensureTrackAhead(run);
1314:     updateParticles(run, dt);
1315: 
1316:     const currentBeat = Math.floor(run.beat);
1317:     while (run.lastBeat < currentBeat) {
1318:       run.lastBeat += 1;
1319:       onBeat(run.lastBeat);
1320:     }
1321: 
1322:     if (!run.tipGate && run.beat > 11.4) {
1323:       run.tipGate = true;
1324:       showToast('STAY LOW', "Don't jump under the laser", 2100);
1325:     }
1326: 
1327:     updateScoreUI();
1328:     updateComboUI();
1329:   }
