1398:   function drawBackground(time, beat, activeRun) {
1399:     const w = view.w;
1400:     const h = view.h;
1401:     const groundY = view.groundY;
1402:     const scale = view.scale;
1403:     const distance = activeRun ? activeRun.worldPos * scale : game.menuTime * 46;
1404:     const pulse = activeRun ? Math.max(0, 1 - mod(activeRun.beat, 1) * 3.6) : 0.35 + Math.sin(time * 2.1) * 0.18;
1405: 
1406:     ctx.fillStyle = skyGradient;
1407:     ctx.fillRect(0, 0, w, groundY + 2);
1408:     ctx.fillStyle = hazeGradient;
1409:     ctx.fillRect(0, 0, w, groundY);
1410: 
1411:     // stars
1412:     const low = view.quality < 0.7;
1413:     ctx.save();
1414:     for (let i = 0; i < stars.length; i += (low ? 2 : 1)) {
1415:       const star = stars[i];
1416:       const sx = mod(star.x * w - distance * star.depth * 0.045, w + 20) - 10;
1417:       const sy = star.y * groundY;
1418:       const twinkle = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(time * star.speed + star.phase));
1419:       ctx.globalAlpha = twinkle * (0.28 + star.depth * 0.55);
1420:       ctx.fillStyle = star.warm ? '#ffc6e4' : '#c7f8ff';
1421:       ctx.fillRect(sx, sy, star.r, star.r);
1422:     }
1423:     ctx.restore();
1424: 
1425:     // sun
1426:     ctx.fillStyle = sunGlowGradient;
1427:     ctx.fillRect(sun.x - sun.r * 2.5, sun.y - sun.r * 2.5, sun.r * 5, sun.r * 5);
1428:     ctx.save();
1429:     ctx.beginPath();
1430:     ctx.arc(sun.x, sun.y, sun.r, 0, TAU);
1431:     ctx.clip();
1432:     ctx.fillStyle = sunGradient;
1433:     ctx.fillRect(sun.x - sun.r, sun.y - sun.r, sun.r * 2, sun.r * 2);
1434:     ctx.fillStyle = 'rgba(7,2,19,0.86)';
1435:     const stripeStart = sun.y + sun.r * 0.08;
1436:     for (let i = 0; i < 8; i += 1) {
1437:       const sy = stripeStart + i * sun.r * 0.115;
1438:       ctx.fillRect(sun.x - sun.r, sy, sun.r * 2, 2 + i * 1.3);
1439:     }
1440:     ctx.restore();
1441:     ctx.strokeStyle = 'rgba(255,164,218,0.38)';
1442:     ctx.lineWidth = 1.2;
1443:     ctx.beginPath();
1444:     ctx.arc(sun.x, sun.y, sun.r + 1.5, 0, TAU);
1445:     ctx.stroke();
1446: 
1447:     // speed streaks
1448:     ctx.save();
1449:     for (let i = 0; i < streaks.length; i += (view.quality < 0.7 ? 2 : 1)) {
1450:       const s = streaks[i];
1451:       const x = mod(s.x * (w + 300) - distance * s.speed * 0.55 - time * 12, w + 300) - 150;
1452:       const y = view.horizon + s.y * (groundY - view.horizon);
1453:       ctx.globalAlpha = s.alpha * (activeRun ? 1 : 0.5);
1454:       ctx.strokeStyle = s.pink ? '#ff3ca6' : '#5cf8ff';
1455:       ctx.lineWidth = 1;
1456:       ctx.beginPath();
1457:       ctx.moveTo(x, y);
1458:       ctx.lineTo(x + s.len, y);
1459:       ctx.stroke();
1460:     }
1461:     ctx.restore();
1462: 
1463:     drawCityDirect(cityFar, distance * 0.1, '#170b38', 0.8, 1);
1464:     drawCityDirect(cityNear, distance * 0.23, '#0d0624', 1, 2);
1465: 
1466:     ctx.fillStyle = horizonGradient;
1467:     ctx.fillRect(0, groundY - 28, w, 32);
1468: 
1469:     drawFloorDirect(distance, time, pulse);
1470:     drawMotes(time, distance);
1471:   }
