1473:   function drawCityDirect(buildings, offset, color, alpha, layer) {
1474:     const groundY = view.groundY;
1475:     const start = -mod(offset, CITY_TILE);
1476:     ctx.save();
1477:     ctx.globalAlpha = alpha;
1478:     for (let copy = 0; copy < 2; copy += 1) {
1479:       const baseX = start + copy * CITY_TILE;
1480:       for (let i = 0; i < buildings.length; i += 1) {
1481:         const b = buildings[i];
1482:         const x = baseX + b.x;
1483:         if (x > view.w + 60 || x + b.w < -60) continue;
1484:         const y = groundY - b.h;
1485:         ctx.fillStyle = color;
1486:         ctx.fillRect(x, y, b.w, b.h + 1);
1487:         ctx.fillStyle = layer === 1 ? 'rgba(255,255,255,0.035)' : 'rgba(92,248,255,0.05)';
1488:         ctx.fillRect(x, y, b.w, 1);
1489:         if (b.antenna) {
1490:           ctx.fillStyle = layer === 1 ? 'rgba(255,60,166,0.3)' : 'rgba(255,60,166,0.55)';
1491:           ctx.fillRect(x + b.w * 0.62, y - 10, 1, 10);
1492:           ctx.fillRect(x + b.w * 0.62 - 1, y - 11, 3, 2);
1493:         }
1494:         const maxWindows = view.quality < 0.7 ? 2 : 7;
1495:         for (let j = 0; j < b.windows.length; j += 1) {
1496:           if (j >= maxWindows) break;
1497:           const win = b.windows[j];
1498:           ctx.fillStyle = win.warm ? 'rgba(255,203,122,0.28)' : 'rgba(255,111,190,0.28)';
1499:           ctx.fillRect(x + win.x, y + win.y, win.w, win.h);
1500:         }
1501:       }
1502:     }
1503:     ctx.restore();
1504:   }
