1506:   function drawFloorDirect(distance, time, pulse) {
1507:     const w = view.w;
1508:     const h = view.h;
1509:     const groundY = view.groundY;
1510:     const depth = h - groundY;
1511: 
1512:     ctx.fillStyle = floorGradient;
1513:     ctx.fillRect(0, groundY, w, depth + 1);
1514: 
1515:     ctx.save();
1516:     ctx.beginPath();
1517:     ctx.rect(0, groundY, w, depth);
1518:     ctx.clip();
1519: 
1520:     for (let i = 1; i <= 9; i += 1) {
1521:       const t = i / 9;
1522:       const y = groundY + depth * Math.pow(t, 1.9);
1523:       ctx.globalAlpha = 0.06 + t * 0.07;
1524:       ctx.strokeStyle = i % 2 ? '#ff3ca6' : '#5cf8ff';
1525:       ctx.beginPath();
1526:       ctx.moveTo(0, y);
1527:       ctx.lineTo(w, y);
1528:       ctx.stroke();
1529:     }
1530:     ctx.globalAlpha = 1;
1531: 
1532:     const horizonX = w * 0.5;
1533:     const spacing = Math.max(88, w / (view.quality < 0.7 ? 6 : 9));
1534:     const shift = mod(distance * 0.24, spacing);
1535:     ctx.strokeStyle = `rgba(92,248,255,${0.05 + pulse * 0.02})`;
1536:     ctx.lineWidth = 1;
1537:     for (let x = -spacing * 2 - shift; x < w + spacing * 2; x += spacing) {
1538:       const topX = horizonX + (x - horizonX) * 0.07;
1539:       ctx.beginPath();
1540:       ctx.moveTo(x, h + 2);
1541:       ctx.lineTo(topX, groundY);
1542:       ctx.stroke();
1543:     }
1544: 
1545:     // scrolling lane dashes just below the track
1546:     const laneY = groundY + 21;
1547:     ctx.globalAlpha = 0.3;
1548:     ctx.strokeStyle = '#ff3ca6';
1549:     ctx.lineWidth = 1;
1550:     ctx.setLineDash([14, 24]);
1551:     ctx.lineDashOffset = -mod(distance * 0.6, 38);
1552:     ctx.beginPath();
1553:     ctx.moveTo(0, laneY);
1554:     ctx.lineTo(w, laneY);
1555:     ctx.stroke();
1556:     ctx.setLineDash([]);
1557: 
1558:     const chevronSpacing = 126;
1559:     const chevronShift = mod(distance * 0.9, chevronSpacing);
1560:     ctx.globalAlpha = 0.18;
1561:     ctx.strokeStyle = '#5cf8ff';
1562:     for (let x = -chevronSpacing - chevronShift; x < w + chevronSpacing; x += chevronSpacing) {
1563:       const cy = groundY + 43;
1564:       ctx.beginPath();
1565:       ctx.moveTo(x + 10, cy);
1566:       ctx.lineTo(x, cy + 7);
1567:       ctx.lineTo(x + 10, cy + 14);
1568:       ctx.stroke();
1569:     }
1570:     ctx.restore();
1571: 
1572:     ctx.save();
1573:     ctx.globalAlpha = 0.22;
1574:     ctx.strokeStyle = '#5cf8ff';
1575:     ctx.lineWidth = 5;
1576:     ctx.beginPath();
1577:     ctx.moveTo(0, groundY);
1578:     ctx.lineTo(w, groundY);
1579:     ctx.stroke();
1580:     ctx.globalAlpha = 0.92;
1581:     ctx.strokeStyle = '#c8feff';
1582:     ctx.lineWidth = 1.4;
1583:     ctx.beginPath();
1584:     ctx.moveTo(0, groundY);
1585:     ctx.lineTo(w, groundY);
1586:     ctx.stroke();
1587:     ctx.restore();
1588: 
1589:     const tickSpacing = 68;
1590:     const tickShift = mod(distance * 0.85, tickSpacing);
1591:     ctx.save();
1592:     for (let x = -tickSpacing - tickShift; x < w + tickSpacing; x += tickSpacing) {
1593:       const major = Math.round((x + tickShift) / tickSpacing) % 4 === 0;
1594:       ctx.globalAlpha = major ? 0.34 : 0.16;
1595:       ctx.fillStyle = major ? '#ff3ca6' : '#5cf8ff';
1596:       ctx.fillRect(x, groundY + 5, major ? 20 : 10, major ? 2 : 1);
1597:     }
1598:     ctx.restore();
1599: 
1600:     ctx.fillStyle = lowerGlowGradient;
1601:     ctx.fillRect(0, groundY, w, 100);
1602:   }
