1604:   function drawMotes(time, distance) {
1605:     ctx.save();
1606:     for (let i = 0; i < motes.length; i += 1) {
1607:       const m = motes[i];
1608:       const x = mod(m.x * view.w - distance * m.drift * 0.08, view.w + 40) - 20;
1609:       const y = view.horizon + mod(m.y * (view.groundY - view.horizon) + Math.sin(time * 0.5 + m.phase) * 18, view.groundY - view.horizon);
1610:       ctx.globalAlpha = 0.18 + 0.28 * (0.5 + 0.5 * Math.sin(time * 1.2 + m.phase));
1611:       ctx.fillStyle = m.size > 2 ? '#ff8ecb' : '#9efaff';
1612:       ctx.beginPath();
