1560:     ctx.globalAlpha = 0.18;
1561:     ctx.strokeStyle = '#5cf8ff';
1562:     for (let x = -chevronSpacing - chevronShift; x < w + chevronSpacing; x += chevronSpacing) {
1563:       const cy = groundY + 43;
