    if (params.get('play') === '1') setTimeout(() => startRun(), 250);

    window.__pulseDash = {
      start: startRun,
      menu: goMenu,
      pause: togglePause,
      get state() { return game.state; },
      get run() { return game.run; },
      get player() { return player; },
      get view() { return view; },
      jump: requestJump,
    };
