.editor-open-btn {
  min-height: 52px;
  border-color: rgba(92, 248, 255, 0.28);
  background: rgba(92, 248, 255, 0.06);
  color: var(--cyan);
}

.editor-screen {
  z-index: 15;
  padding: clamp(12px, 2.5vw, 32px);
  background: rgba(3, 2, 12, 0.94);
  backdrop-filter: blur(18px);
}

.editor-shell {
  width: min(1180px, 96vw);
  max-height: 92vh;
  margin: auto;
  border: 1px solid rgba(92, 248, 255, 0.18);
  background: linear-gradient(145deg, rgba(13, 8, 35, 0.98), rgba(5, 3, 18, 0.98));
  box-shadow: 0 24px 90px rgba(0, 0, 0, 0.58), inset 0 1px rgba(255, 255, 255, 0.04);
  clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px);
}

.editor-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 76px;
  padding: 12px 18px 12px 24px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.editor-header h2 { margin: 3px 0 0; font-size: clamp(18px, 2.4vw, 28px); }
.editor-close { width: 42px; height: 42px; }

.editor-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  overflow-x: auto;
}

.editor-toolbar label {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
}

.editor-toolbar input,
.editor-toolbar select {
  height: 38px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.05);
  color: #fff;
  font-family: var(--mono);
}
.editor-toolbar input { width: 68px; padding: 0 8px; }
.editor-toolbar select { min-width: 94px; padding: 0 8px; }

.tool-btn {
  flex: none;
  height: 38px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.04);
  color: #fff;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
}
.tool-btn.accent { border-color: rgba(255, 60, 166, 0.48); background: rgba(255, 60, 166, 0.16); color: #ffaad4; }

.editor-workspace {
  display: grid;
  grid-template-columns: 112px minmax(0, 1fr);
  min-height: min(62vh, 560px);
}

.tile-palette {
  display: grid;
  align-content: start;
  gap: 6px;
  padding: 12px;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
}

.tile-tool {
  display: grid;
  grid-template-columns: 34px 1fr;
  align-items: center;
  height: 48px;
  padding: 6px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-align: left;
}
