.tile-icon { position: relative; display: block; width: 28px; height: 28px; }
.spike-icon::before { content: ""; position: absolute; left: 3px; bottom: 3px; width: 22px; height: 22px; background: var(--pink); clip-path: polygon(50% 0,100% 100%,0 100%); }
