.editor-cell.tile-tall::before { height:68%; width:42%; }
.editor-cell.tile-block::before { height:48%; width:58%; clip-path:none; border-radius:3px; }
.editor-cell.tile-gate::before { bottom:68%; height:8%; width:72%; clip-path:none; background:var(--cyan); box-shadow:0 0 16px var(--cyan); }
.editor-cell.tile-gem::before { bottom:38%; width:28%; height:28%; clip-path:none; transform:translateX(-50%) rotate(45deg); background:var(--yellow); }

